/// <reference path="../References.d.ts"/>
import * as React from 'react';
import * as Blueprint from "@blueprintjs/core"
import * as Icons from '@blueprintjs/icons';
import * as Theme from '../Theme';
import * as Constants from '../Constants';
import * as SubscriptionTypes from '../types/SubscriptionTypes';
import SubscriptionStore from '../stores/SubscriptionStore';
import CompletionStore from "../stores/CompletionStore";
import LoadingBar from './LoadingBar';
import Subscription from './Subscription';
import Users from './Users';
import UserDetailed from './UserDetailed';
import Nodes from './Nodes';
import Policies from './Policies';
import Certificates from './Certificates';
import Secrets from './Secrets';
import Organizations from './Organizations';
import Datacenters from './Datacenters';
import Alerts from './Alerts';
import Zones from './Zones';
import Shapes from './Shapes';
import Blocks from './Blocks';
import Vpcs from './Vpcs';
import Domains from './Domains';
import Plans from './Plans';
import Balancers from './Balancers';
import Storages from './Storages';
import Images from './Images';
import Pools from './Pools';
import Disks from './Disks';
import Advisories from './Advisories';
import Instances from './Instances';
import Pods from './Pods';
import Firewalls from './Firewalls';
import Authorities from './Authorities';
import Logs from './Logs';
import Settings from './Settings';
import OrganizationSelect from './OrganizationSelect';
import * as Router from '../Router';
import RouterRoute from './RouterRoute';
import RouterRoutes from './RouterRoutes';
import RouterLink from './RouterLink';
import RouterRedirect from './RouterRedirect';
import * as CompletionActions from '../actions/CompletionActions';
import * as SubscriptionActions from '../actions/SubscriptionActions';

interface State {
	subscription: SubscriptionTypes.SubscriptionRo;
	organization: string;
	disabled: boolean;
}

const css = {
	app: {
		display: 'grid',
		gridTemplateRows: 'auto 1fr',
		height: '100vh',
		overflow: 'hidden',
	} as React.CSSProperties,
	card: {
		minWidth: '310px',
		maxWidth: '380px',
		width: 'calc(100% - 20px)',
		margin: '60px auto',
	} as React.CSSProperties,
	nav: {
		height: 'auto',
		userSelect: 'none',
		gap: '5px',
	} as React.CSSProperties,
	navTitle: {
		height: 'auto',
		flexWrap: 'wrap',
		gap: '5px',
		padding: '8px 0',
		alignContent: 'center',
	} as React.CSSProperties,
	navGroup: {
		flexWrap: 'wrap',
		height: 'auto',
		padding: '10px 0',
	} as React.CSSProperties,
	link: {
		padding: '0 7px',
		color: 'inherit',
	} as React.CSSProperties,
	sub: {
		color: 'inherit',
	} as React.CSSProperties,
	heading: {
		marginRight: '11px',
		fontSize: '18px',
		fontWeight: 'bold',
		width: '100px',
	} as React.CSSProperties,
	content: {
		overflowY: 'auto',
		minHeight: 0,
	} as React.CSSProperties,
};

export default class Main extends React.Component<{}, State> {
	constructor(props: any, context: any) {
		super(props, context);
		this.state = {
			subscription: SubscriptionStore.subscription,
			organization: CompletionStore.userOrganization,
			disabled: false,
		};
	}

	componentDidMount(): void {
		if (!Constants.user) {
			SubscriptionStore.addChangeListener(this.onChange);
			SubscriptionActions.sync(false);
		} else {
			CompletionStore.addChangeListener(this.onChange);
			CompletionActions.sync();
		}
	}

	componentWillUnmount(): void {
		if (!Constants.user) {
			SubscriptionStore.removeChangeListener(this.onChange);
		} else {
			CompletionStore.removeChangeListener(this.onChange);
		}
	}

	onChange = (): void => {
		this.setState({
			...this.state,
			subscription: SubscriptionStore.subscription,
			organization: CompletionStore.userOrganization,
		});
	}

	render(): JSX.Element {
		if ((!Constants.user && !this.state.subscription) ||
				(Constants.user && this.state.organization === undefined)) {
			return <div/>;
		}

		if (Constants.user && !this.state.organization) {
			return <div style={css.card}>
				<Blueprint.Callout
					intent="danger"
					title="No Organization"
					icon={<Icons.Error/>}
				>
					Account does not have access to any organizations
					<button
						className="bp5-button bp5-minimal bp5-intent-danger bp5-icon-log-out"
						onClick={() => {
							window.location.href = '/logout';
						}}
					>Logout</button>
				</Blueprint.Callout>
			</div>;
		}

		return <div style={css.app}>
			<nav className="bp5-navbar layout horizontal" style={css.nav}>
				<div
					className="bp5-navbar-group bp5-align-left flex"
					style={css.navTitle}
				>
					<img className="logo-light bp5-navbar-heading" style={css.heading} src="data:image/png;base64," alt="Pritunl Cloud"/>
					<img className="logo-dark bp5-navbar-heading" style={css.heading} src="data:image/png;base64," alt="Pritunl Cloud"/>
					<OrganizationSelect hidden={!Constants.user}/>
				</div>
				<div className="bp5-navbar-group bp5-align-right" style={css.navGroup}>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-dashboard"
						style={css.link}
						to="/instances"
					>
						Instances
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-server"
						style={css.link}
						to="/pods"
					>
						Pods
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-floppy-disk"
						style={css.link}
						to="/disks"
					>
						Disks
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-compressed"
						style={css.link}
						to="/images"
					>
						Images
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-shield"
						style={css.link}
						to="/firewalls"
					>
						Firewalls
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-layout-auto"
						style={css.link}
						to="/vpcs"
					>
						VPCs
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-map-marker"
						style={css.link}
						to="/domains"
					>
						Domains
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-random"
						style={css.link}
						to="/balancers"
					>
						Load Balancers
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-key"
						style={css.link}
						to="/secrets"
					>
						Secrets
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-office"
						style={css.link}
						to="/authorities"
					>
						Authorities
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-warning-sign"
						style={css.link}
						to="/advisories"
					>
						Advisories
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-control"
						style={css.link}
						hidden={Constants.user}
						to="/pools"
					>
						Disk Pools
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-ip-address"
						style={css.link}
						hidden={Constants.user}
						to="/blocks"
					>
						IP Blocks
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-layers"
						style={css.link}
						hidden={Constants.user}
						to="/nodes"
					>
						Nodes
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-zoom-to-fit"
						style={css.link}
						hidden={Constants.user}
						to="/shapes"
					>
						Shapes
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-map-marker"
						style={css.link}
						to="/plans"
					>
						Plans
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-people"
						style={css.link}
						hidden={Constants.user}
						to="/organizations"
					>
						Organizations
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-people"
						style={css.link}
						hidden={Constants.user}
						to="/users"
					>
						Users
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-filter"
						style={css.link}
						hidden={Constants.user}
						to="/policies"
					>
						Policies
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-endorsed"
						style={css.link}
						to="/certificates"
					>
						Certificates
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-database"
						style={css.link}
						hidden={Constants.user}
						to="/storages"
					>
						Storages
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-cloud"
						style={css.link}
						hidden={Constants.user}
						to="/datacenters"
					>
						Datacenters
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-layout-circle"
						style={css.link}
						hidden={Constants.user}
						to="/zones"
					>
						Zones
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-notifications"
						style={css.link}
						to="/alerts"
					>
						Alerts
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-history"
						style={css.link}
						hidden={Constants.user}
						to="/logs"
					>
						Logs
					</RouterLink>
					<RouterLink
						className="bp5-button bp5-minimal bp5-icon-settings"
						style={css.link}
						hidden={Constants.user}
						to="/settings"
					>
						Settings
					</RouterLink>
					<RouterLink
						to="/subscription"
						style={css.sub}
						hidden={Constants.user}
					>
						<button
							className="bp5-button bp5-minimal bp5-icon-credit-card"
							style={css.link}
							onClick={(): void => {
								SubscriptionActions.sync(true);
							}}
						>Subscription</button>
					</RouterLink>
					<a
						className="bp5-button bp5-minimal bp5-icon-comment"
						style={css.link}
						href="https://forum.pritunl.com"
						target="_blank"
					>Community Forum</a>
					<button
						className="bp5-button bp5-minimal bp5-icon-refresh"
						disabled={this.state.disabled}
						onClick={() => {
							this.setState({
								...this.state,
								disabled: true,
							});
							Router.refresh(() => {
								this.setState({
									...this.state,
									disabled: false,
								});
							})
						}}
					>Refresh</button>
					<button
						className="bp5-button bp5-minimal bp5-icon-log-out"
						onClick={() => {
							window.location.href = '/logout';
						}}
					>Logout</button>
					<button
						className="bp5-button bp5-minimal bp5-icon-moon"
						onClick={(evt): void => {
							Theme.toggle(evt.shiftKey);
							Theme.save();
						}}
					/>
				</div>
				<LoadingBar intent="primary"/>
			</nav>
			<div style={css.content}>
				<RouterRoutes>
					<RouterRoute path="/" render={() => (
						<Instances/>
					)}/>
					<RouterRoute path="/reload" render={() => (
						<RouterRedirect to="/"/>
					)}/>
					<RouterRoute path="/instances" render={() => (
						<Instances/>
					)}/>
					<RouterRoute path="/instances/:instance" render={(data) => (
						<Instances instanceId={data.params.instance}/>
					)}/>
					<RouterRoute path="/pods" render={() => (
						<Pods/>
					)}/>
					<RouterRoute path="/disks" render={() => (
						<Disks/>
					)}/>
					<RouterRoute path="/advisories" render={() => (
						<Advisories/>
					)}/>
					<RouterRoute path="/images" render={() => (
						<Images/>
					)}/>
					<RouterRoute path="/firewalls" render={() => (
						<Firewalls/>
					)}/>
					<RouterRoute path="/vpcs" render={() => (
						<Vpcs/>
					)}/>
					<RouterRoute path="/domains" render={() => (
						<Domains/>
					)}/>
					<RouterRoute path="/balancers" render={() => (
						<Balancers/>
					)}/>
					<RouterRoute path="/pools" render={() => (
						<Pools/>
					)}/>
					<RouterRoute path="/blocks" render={() => (
						<Blocks/>
					)}/>
					<RouterRoute path="/nodes" render={() => (
						<Nodes/>
					)}/>
					<RouterRoute path="/shapes" render={() => (
						<Shapes/>
					)}/>
					<RouterRoute path="/plans" render={() => (
						<Plans/>
					)}/>
					<RouterRoute path="/organizations" render={() => (
						<Organizations/>
					)}/>
					<RouterRoute path="/users" render={() => (
						<Users/>
					)}/>
					<RouterRoute path="/user" render={() => (
						<UserDetailed/>
					)}/>
					<RouterRoute path="/user/:userId" render={(data) => (
						<UserDetailed userId={data.params.userId}/>
					)}/>
					<RouterRoute path="/policies" render={() => (
						<Policies/>
					)}/>
					<RouterRoute path="/certificates" render={() => (
						<Certificates/>
					)}/>
					<RouterRoute path="/secrets" render={() => (
						<Secrets/>
					)}/>
					<RouterRoute path="/authorities" render={() => (
						<Authorities/>
					)}/>
					<RouterRoute path="/storages" render={() => (
						<Storages/>
					)}/>
					<RouterRoute path="/datacenters" render={() => (
						<Datacenters/>
					)}/>
					<RouterRoute path="/zones" render={() => (
						<Zones/>
					)}/>
					<RouterRoute path="/alerts" render={() => (
						<Alerts/>
					)}/>
					<RouterRoute path="/logs" render={() => (
						<Logs/>
					)}/>
					<RouterRoute path="/settings" render={() => (
						<Settings/>
					)}/>
					<RouterRoute path="/subscription" render={() => (
						<Subscription/>
					)}/>
				</RouterRoutes>
			</div>
		</div>;
	}
}
