/// <reference path="../References.d.ts"/>
import * as React from 'react';
import * as Blueprint from "@blueprintjs/core"
import CopyButton from './CopyButton';

export interface Field {
	valueClass?: string;
	valueClasses?: string[];
	key?: string;
	label: string;
	value?: string | number | string[] | LinkValue[];
	hover?: JSX.Element;
	link?: string;
	copy?: boolean;
	embedded?: Props;
	maxLines?: number;
}

export interface LinkValue {
	value?: string;
	link?: string;
}

export interface Bar {
	progressClass?: string;
	label?: string;
	value: number;
	color?: string;
}

export interface Props {
	style?: React.CSSProperties;
	hidden?: boolean;
	fields?: Field[];
	bars?: Bar[];
	compact?: boolean;
	embedded?: boolean;
}

const css = {
	label: {
		width: '100%',
		maxWidth: '320px',
	} as React.CSSProperties,
	labelEmbedded: {
		width: '100%',
		maxWidth: '320px',
		marginBottom: '0px',
	} as React.CSSProperties,
	value: {
		wordWrap: 'break-word',
	} as React.CSSProperties,
	valueLimit: {
		wordWrap: 'break-word',
		display: '-webkit-box',
		WebkitBoxOrient: 'vertical',
		overflow: 'hidden',
		textOverflow: 'ellipsis',
	} as React.CSSProperties,
	item: {
		marginTop: '0px',
		marginBottom: '5px',
	} as React.CSSProperties,
	itemLast: {
		marginTop: '0px',
		marginBottom: '0px',
	} as React.CSSProperties,
	itemCompact: {
		marginTop: '0px',
		marginBottom: '2px',
	} as React.CSSProperties,
	hoverValue: {
		display: 'inline',
		textDecoration: 'underline',
	} as React.CSSProperties,
	bar: {
		maxWidth: '280px',
	} as React.CSSProperties,
	embedded: {
		minWidth: '300px',
		padding: '10px',
		maxHeight: '320px',
		overflowY: 'auto',
	} as React.CSSProperties,
	link: {
		verticalAlign: 'middle',
		cursor: 'pointer',
		marginLeft: '3px',
		position: 'relative',
		top: '-1px',
		opacity: 0.8,
	} as React.CSSProperties,
};

export default class PageInfo extends React.Component<Props, {}> {
	render(): JSX.Element {
		let fields: JSX.Element[] = [];
		let bars: JSX.Element[] = [];
		let itemStyle = this.props.compact ? css.itemCompact : css.item;

		(this.props.fields || []).forEach((field, index, array) => {
			if (field == null) {
				return;
			}

			if (this.props.embedded && index === array.length - 1) {
				itemStyle = css.itemLast
			}

			let value: string | JSX.Element[];
			let copyBtn: JSX.Element;
			let linkBtn: JSX.Element;

			if (typeof field.value === 'string') {
				value = field.value;
				if (field.copy) {
					copyBtn = <CopyButton
						value={field.value}
					/>;
				}
			} else if (typeof field.value === 'number') {
				value = field.value.toString();
				if (field.copy) {
					copyBtn = <CopyButton
						value={field.value.toString()}
					/>;
				}
			} else if (field.value) {
				value = [];
				for (let i = 0; i < field.value.length; i++) {
					let item = field.value[i];
					let itemValue: string;
					let itemLink: string;

					if (typeof item === 'object') {
						itemValue = item.value;
						itemLink = item.link;
					} else {
						itemValue = item;
					}

					let copyItemBtn: JSX.Element;

					if (field.copy) {
						copyItemBtn = <CopyButton
							value={itemValue}
						/>;
					}

					let itemContent: string | JSX.Element = itemValue;
					if (itemLink) {
						itemContent = <a
							target="_blank"
							href={itemLink}
						>
							{itemValue}
						</a>;
					}

					value.push(
						<div
							key={i}
							className={
								field.valueClasses ?
								field.valueClasses[i] :
								(field.valueClass || 'bp5-text-muted')
							}
						>
							{itemContent}{copyItemBtn}
						</div>
					);
				}
			}

			if (field.link) {
				linkBtn = <a
					target="_blank"
					href={field.link}
				>
					<span
						style={css.link}
						className="bp5-icon-standard bp5-icon-document-open bp5-intent-primary"
					/>
				</a>
			}

			if (field.hover || field.embedded) {
				fields.push(
					<div style={itemStyle}>
						{field.label}{linkBtn}
						<div
							className={field.valueClass || 'bp5-text-muted'}
							style={css.value}
						>
							<Blueprint.Popover
								key={field.label}
								interactionKind="hover"
								placement="bottom"
								minimal={true}
								hoverCloseDelay={150}
								hoverOpenDelay={0}
								content={field.hover || <div
									style={css.embedded}
									className="bp5-content-popover">
										<PageInfo embedded={true} {...field.embedded}/>
									</div>
								}
								renderTarget={({isOpen, ...targetProps}): JSX.Element => {
									return <span
										{...targetProps}
										style={field.embedded ? {} : css.hoverValue}
									>
										{value}{copyBtn}
									</span>
								}}
							/>
						</div>
					</div>,
				);
			} else {
				let style = css.value
				if (field.maxLines) {
					style = {...css.valueLimit}
					style.WebkitLineClamp = field.maxLines
				}

				fields.push(
					<div key={field.key || field.label} style={itemStyle}>
						{field.label}{linkBtn}
						<div
							className={field.valueClass || 'bp5-text-muted'}
							style={style}
						>
							{value}{copyBtn}
						</div>
					</div>,
				);
			}
		})

		if (this.props.bars) {
			for (let i = 0; i < this.props.bars.length; i++) {
				let bar = this.props.bars[i]

				let style: React.CSSProperties = {
					width: (bar.value || 0) + '%',
				};

				if (bar.color) {
					style.backgroundColor = bar.color;
				}

				bars.push(
					<div key={bar.label || i} style={itemStyle}>
						{bar.label}
						<div
							className={'bp5-progress-bar ' + (bar.progressClass || '')}
							style={css.bar}
						>
							<div className="bp5-progress-meter" style={style}/>
						</div>
					</div>,
				);
			}
		}

		let labelStyle: React.CSSProperties;
		if (this.props.embedded) {
			labelStyle = css.labelEmbedded
		} else {
			labelStyle = css.label
		}

		if (this.props.style) {
			labelStyle = {
				...labelStyle,
				...this.props.style,
			};
		}

		return <label
			className="bp5-label"
			style={labelStyle}
			hidden={this.props.hidden}
		>
			{fields}
			{bars}
		</label>;
	}
}
